package com.nequard.network;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="network_interfaces") public class NetworkInterface{@Id @GeneratedValue(strategy=GenerationType.UUID)UUID id;@Column(nullable=false)UUID deviceId;@Column(nullable=false)String name;String description,status="UNKNOWN",speedMbps,duplex;Double trafficInMbps,trafficOutMbps,errorRate,utilizationPercent;Instant updatedAt=Instant.now();public UUID getId(){return id;}public UUID getDeviceId(){return deviceId;}public void setDeviceId(UUID v){deviceId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public String getSpeedMbps(){return speedMbps;}public void setSpeedMbps(String v){speedMbps=v;}public String getDuplex(){return duplex;}public void setDuplex(String v){duplex=v;}public Double getTrafficInMbps(){return trafficInMbps;}public void setTrafficInMbps(Double v){trafficInMbps=v;}public Double getTrafficOutMbps(){return trafficOutMbps;}public void setTrafficOutMbps(Double v){trafficOutMbps=v;}public Double getErrorRate(){return errorRate;}public void setErrorRate(Double v){errorRate=v;}public Double getUtilizationPercent(){return utilizationPercent;}public void setUtilizationPercent(Double v){utilizationPercent=v;}public Instant getUpdatedAt(){return updatedAt;}}